    DiagnosticDispositionV1, DiagnosticEffectCertaintyV1, DiagnosticFactV1Wire, DiagnosticRetryV1,
    DiagnosticSourceV1Wire, DiagnosticStageV1, DiagnosticSubjectV1Wire,
};
