/// Freshness class accepted by [`ObservationFilter`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum ObservationFreshnessClass {
    /// Current for the snapshot.
    Fresh,
